// Generated by AI (UnitTest MCP)
import { execFileSync, spawnSync } from "node:child_process";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { afterEach, describe, expect, it } from "vitest";

import { reserveWorktreePath } from "./test-support/reserve-worktree-path.mjs";

const scopedCommit = join(
  dirname(fileURLToPath(import.meta.url)),
  "../../../scripts/scoped-commit.mjs"
);
const temporaryDirectories = [];
const gitRepositoryVariables = [
  "GIT_DIR",
  "GIT_WORK_TREE",
  "GIT_COMMON_DIR",
  "GIT_INDEX_FILE",
  "GIT_OBJECT_DIRECTORY",
  "GIT_ALTERNATE_OBJECT_DIRECTORIES",
];

const isolatedGitEnvironment = () => {
  const isolated = { ...process.env, PRE_COMMIT_ALLOW_NO_CONFIG: "1" };
  for (const variable of gitRepositoryVariables) {
    delete isolated[variable];
  }
  // Tests must not inherit the ambient agent identity of whoever runs them, or
  // the worktree-ownership guard would behave differently in a fleet than in CI.
  delete isolated.LODESTAR_SESSION_ID;
  return isolated;
};

afterEach(() => {
  for (const directory of temporaryDirectories.splice(0)) {
    rmSync(directory, { recursive: true, force: true });
  }
});

const git = (cwd, args) =>
  execFileSync("git", args, {
    cwd,
    encoding: "utf8",
    stdio: "pipe",
    env: isolatedGitEnvironment(),
  }).trim();

describe("scoped-commit", () => {
  it("commits only declared paths and preserves another agent's staged work", () => {
    const repo = mkdtempSync(join(tmpdir(), "mindleak-scoped-commit-"));
    temporaryDirectories.push(repo);
    git(repo, ["init", "-b", "main"]);
    git(repo, ["config", "user.name", "Scoped Commit Test"]);
    git(repo, ["config", "user.email", "scoped-commit@example.invalid"]);
    writeFileSync(join(repo, "base.txt"), "base\n");
    git(repo, ["add", "base.txt"]);
    git(repo, ["commit", "-m", "base"]);

    writeFileSync(join(repo, "mine.txt"), "declared\n");
    writeFileSync(join(repo, "foreign.txt"), "another agent\n");
    git(repo, ["add", "foreign.txt"]);

    const result = spawnSync(process.execPath, [scopedCommit, "-m", "scoped", "--", "mine.txt"], {
      cwd: repo,
      encoding: "utf8",
      env: isolatedGitEnvironment(),
    });

    expect(result.status, `${result.stdout}\n${result.stderr}`).toBe(0);
    expect(git(repo, ["show", "--name-only", "--format=", "HEAD"])).toBe("mine.txt");
    expect(git(repo, ["diff", "--cached", "--name-only"])).toBe("foreign.txt");
    expect(result.stderr).toMatch(/staged paths are not yours/);
  }, 30_000);

  // The pre-commit stash race (ADR-0038). pre-commit stashes every unstaged
  // change around the hook run; when a second worktree means a second agent may
  // be writing, that restore can collide and the hooks report a fictitious
  // failure that is very hard to trace back to the real cause.
  const repoWithSecondWorktree = () => {
    const repo = mkdtempSync(join(tmpdir(), "mindleak-stash-race-"));
    temporaryDirectories.push(repo);
    git(repo, ["init", "-b", "main"]);
    git(repo, ["config", "user.name", "Stash Race Test"]);
    git(repo, ["config", "user.email", "stash-race@example.invalid"]);
    writeFileSync(join(repo, "base.txt"), "base\n");
    writeFileSync(join(repo, "theirs.txt"), "theirs\n");
    git(repo, ["add", "base.txt", "theirs.txt"]);
    git(repo, ["commit", "-m", "base"]);
    return repo;
  };

  const attachWorktree = (repo) => {
    // Reserve a not-yet-created path rather than mkdtemp-then-delete it, which
    // raced `git worktree add` recreating it at the same name
    // (gaps.d/a-scoped-commit-fixture-can-fall-outside-its-repository.md).
    const { parent, path: linked } = reserveWorktreePath("mindleak-stash-race-linked-");
    temporaryDirectories.push(parent);
    git(repo, ["worktree", "add", linked, "-b", "fleet/other"]);
    return linked;
  };

  const commit = (repo, args) =>
    spawnSync(process.execPath, [scopedCommit, ...args], {
      cwd: repo,
      encoding: "utf8",
      env: isolatedGitEnvironment(),
    });

  it("refuses to commit over another agent's unstaged work when a fleet is live", () => {
    const repo = repoWithSecondWorktree();
    attachWorktree(repo);

    writeFileSync(join(repo, "mine.txt"), "declared\n");
    // Another agent's live, unstaged edit in this same working tree.
    writeFileSync(join(repo, "theirs.txt"), "being edited right now\n");

    const result = commit(repo, ["-m", "scoped", "--", "mine.txt"]);

    expect(result.status).toBe(3);
    expect(result.stderr).toMatch(/refusing to commit/);
    expect(result.stderr).toMatch(/theirs\.txt/);
    expect(result.stderr).toMatch(/worktree add/);
    // Nothing was committed, and their edit is untouched.
    expect(git(repo, ["log", "--oneline"]).split("\n")).toHaveLength(1);
  }, 30_000);

  it("still commits when the only unstaged work is inside the declared paths", () => {
    // The guard must not fire on your own in-progress edits, or it would just
    // train people to pass the escape hatch every time.
    const repo = repoWithSecondWorktree();
    attachWorktree(repo);
    writeFileSync(join(repo, "mine.txt"), "declared\n");

    const result = commit(repo, ["-m", "scoped", "--", "mine.txt"]);

    expect(result.status, `${result.stdout}\n${result.stderr}`).toBe(0);
    expect(git(repo, ["show", "--name-only", "--format=", "HEAD"])).toBe("mine.txt");
  }, 30_000);

  it("does not fire inside a linked worktree, which belongs to one agent", () => {
    // The danger is the shared primary checkout, not the existence of a fleet.
    // Firing in your own worktree would make the guard noise, and noise is how
    // a guard turns into a reflexive --allow-foreign-wip.
    const repo = repoWithSecondWorktree();
    const linked = attachWorktree(repo);

    writeFileSync(join(linked, "mine.txt"), "declared\n");
    writeFileSync(join(linked, "theirs.txt"), "my own unrelated wip\n");

    const result = commit(linked, ["-m", "scoped", "--", "mine.txt"]);

    expect(result.status, `${result.stdout}\n${result.stderr}`).toBe(0);
    expect(git(linked, ["show", "--name-only", "--format=", "HEAD"])).toBe("mine.txt");
  }, 30_000);

  it("does not fire for a single operator with one working tree", () => {
    // Unrelated WIP is normal and harmless when nobody else can write here.
    const repo = repoWithSecondWorktree();
    writeFileSync(join(repo, "mine.txt"), "declared\n");
    writeFileSync(join(repo, "theirs.txt"), "my own unrelated wip\n");

    const result = commit(repo, ["-m", "scoped", "--", "mine.txt"]);

    expect(result.status, `${result.stdout}\n${result.stderr}`).toBe(0);
    expect(git(repo, ["show", "--name-only", "--format=", "HEAD"])).toBe("mine.txt");
  }, 30_000);

  it("lets a single operator override deliberately", () => {
    const repo = repoWithSecondWorktree();
    attachWorktree(repo);
    writeFileSync(join(repo, "mine.txt"), "declared\n");
    writeFileSync(join(repo, "theirs.txt"), "mine really\n");

    const result = commit(repo, ["-m", "scoped", "--allow-foreign-wip", "--", "mine.txt"]);

    expect(result.status, `${result.stdout}\n${result.stderr}`).toBe(0);
    expect(git(repo, ["show", "--name-only", "--format=", "HEAD"])).toBe("mine.txt");
  }, 30_000);

  // Worktree ownership (ADR-0038). The guard above deliberately does not fire in
  // a linked worktree because "a linked worktree belongs to one agent" — but
  // nothing enforced *which* agent. An agent cd-ing into a peer's worktree and
  // committing there raced that peer's edits and corrupted their in-flight
  // merge. Ownership is now recorded on first commit and checked on every one.
  const commitAs = (cwd, session, args) =>
    spawnSync(process.execPath, [scopedCommit, ...args], {
      cwd,
      encoding: "utf8",
      env: { ...isolatedGitEnvironment(), LODESTAR_SESSION_ID: session },
    });

  it("refuses to commit in a worktree owned by another agent", () => {
    const repo = repoWithSecondWorktree();
    const linked = attachWorktree(repo);

    // The owning agent commits first, which records ownership.
    writeFileSync(join(linked, "theirs.txt"), "owner's work\n");
    const owner = commitAs(linked, "session-owner", ["-m", "owner", "--", "theirs.txt"]);
    expect(owner.status, `${owner.stdout}\n${owner.stderr}`).toBe(0);

    // A different agent wanders in.
    writeFileSync(join(linked, "mine.txt"), "intruder\n");
    const intruder = commitAs(linked, "session-intruder", ["-m", "scoped", "--", "mine.txt"]);

    expect(intruder.status).toBe(4);
    expect(intruder.stderr).toMatch(/belongs to another agent/);
    expect(intruder.stderr).toMatch(/session-owner/);
    expect(intruder.stderr).toMatch(/worktree add/);
    // Their history is untouched and nothing of the intruder's was staged.
    expect(git(linked, ["log", "--oneline"]).split("\n")).toHaveLength(2);
    expect(git(linked, ["diff", "--cached", "--name-only"])).toBe("");
  }, 30_000);

  it("lets the owning agent keep committing in its own worktree", () => {
    const repo = repoWithSecondWorktree();
    const linked = attachWorktree(repo);

    writeFileSync(join(linked, "mine.txt"), "first\n");
    expect(commitAs(linked, "session-owner", ["-m", "one", "--", "mine.txt"]).status).toBe(0);
    writeFileSync(join(linked, "mine.txt"), "second\n");
    const again = commitAs(linked, "session-owner", ["-m", "two", "--", "mine.txt"]);

    expect(again.status, `${again.stdout}\n${again.stderr}`).toBe(0);
    expect(git(linked, ["log", "--oneline"]).split("\n")).toHaveLength(3);
  }, 30_000);

  it("allows a deliberate handover with --adopt-worktree", () => {
    const repo = repoWithSecondWorktree();
    const linked = attachWorktree(repo);

    writeFileSync(join(linked, "theirs.txt"), "owner's work\n");
    commitAs(linked, "session-owner", ["-m", "owner", "--", "theirs.txt"]);

    writeFileSync(join(linked, "mine.txt"), "handed over\n");
    const adopted = commitAs(linked, "session-next", [
      "-m",
      "scoped",
      "--adopt-worktree",
      "--",
      "mine.txt",
    ]);

    expect(adopted.status, `${adopted.stdout}\n${adopted.stderr}`).toBe(0);
    // Ownership transferred, so the original owner is now the one refused.
    writeFileSync(join(linked, "theirs.txt"), "coming back\n");
    const rebuffed = commitAs(linked, "session-owner", ["-m", "back", "--", "theirs.txt"]);
    expect(rebuffed.status).toBe(4);
  }, 30_000);

  it("stays out of the way when no session identity is set", () => {
    // A human running the script directly is not an agent in the fleet, and
    // must not be locked out of their own worktree.
    const repo = repoWithSecondWorktree();
    const linked = attachWorktree(repo);

    writeFileSync(join(linked, "theirs.txt"), "owner's work\n");
    commitAs(linked, "session-owner", ["-m", "owner", "--", "theirs.txt"]);

    writeFileSync(join(linked, "mine.txt"), "human\n");
    const human = commit(linked, ["-m", "human", "--", "mine.txt"]);

    expect(human.status, `${human.stdout}\n${human.stderr}`).toBe(0);
  }, 30_000);
});
